<script setup lang="ts">
const api=window.teachshelf;
import {computed,nextTick,onMounted,onUnmounted,ref,watchEffect} from 'vue';
import {AlertCircle,ChevronLeft,Download,FolderOpen,LoaderCircle,Plus,RefreshCw,Settings,Upload,X} from 'lucide-vue-next';
import type {Course} from '../shared/model';
import {useLibrary} from './stores/library';
import Sidebar from './components/Sidebar.vue';
import CourseEditor from './components/CourseEditor.vue';
import ImportDialog from './components/ImportDialog.vue';
import Modal from './components/Modal.vue';
import WebsiteDialog from './components/WebsiteDialog.vue';
import TaskEditor from './components/TaskEditor.vue';
import LibraryView from './views/LibraryView.vue';
import PlansView from './views/PlansView.vue';
import TimetableView from './views/TimetableView.vue';
import ChatView from './views/ChatView.vue';
import SettingsView from './views/SettingsView.vue';
const hasAPI=!!api;
const store=useLibrary(),courseEditor=ref<Course|null|undefined>(undefined),showImport=ref(false),showWebsite=ref(false),websiteKind=ref<'teaching'|'timetable'>('teaching'),showTask=ref(false),loaded=ref(false);const releases:(()=>void)[]=[];
const theme=computed(()=>store.settings?.theme??store.state.appearance);
watchEffect(()=>{document.documentElement.dataset.theme=theme.value;document.documentElement.style.setProperty('--accent',store.state.accentColor||'#39786B');});
function openWebsite(kind:'teaching'|'timetable'='teaching'){websiteKind.value=kind;showWebsite.value=true;}
function editCourse(course?:Course){courseEditor.value=course??null;}
function menu(action:string){switch(action){case 'new-course':case 'create-course':editCourse();break;case 'import':case 'import-files':showImport.value=true;break;case 'settings':store.navigate('settings');break;case 'all':store.navigate('all');break;case 'plans':store.navigate('plans');break;case 'ai':store.navigate('assistant');break;case 'new-task':case 'new-plan':showTask.value=true;break;case 'open-library':void store.chooseLibrary(false);break;case 'import-library':void store.chooseLibrary(true);break;case 'sync':void store.change(()=>api.sync(),'资料库已同步');break;}}
function key(e:KeyboardEvent){if(!(e.metaKey||e.ctrlKey))return;if(e.key.toLowerCase()==='o'){e.preventDefault();showImport.value=true;}if(e.key.toLowerCase()==='n'){e.preventDefault();if(e.shiftKey)showTask.value=true;else editCourse();}if(e.key===','){e.preventDefault();store.navigate('settings');}}
onMounted(async()=>{if(!api){store.error='此界面需要从 Electron 桌面应用启动，请运行 npm run dev 或安装应用。';loaded.value=true;return;}releases.push(api.onChanged(store.accept),api.onMenu(menu));window.addEventListener('keydown',key);await store.refresh();const settings=await store.run(()=>api.settings(),'本地资料库已就绪');if(settings)store.settings=settings;loaded.value=true;});onUnmounted(()=>{releases.forEach(fn=>fn());window.removeEventListener('keydown',key);});
</script>
<template><div class="app-shell"><div class="titlebar"><span class="titlebar-brand">课屿</span><span class="titlebar-caption">课程与资料</span><div class="titlebar-actions"><button class="icon-button" aria-label="同步文件" title="同步文件" :disabled="!!store.busy||!store.snapshot" @click="store.change(()=>api.sync(),'资料库已同步')"><RefreshCw :size="17" :class="{spinning:store.busy}"/></button><button class="icon-button" aria-label="打开设置" title="设置" @click="store.navigate('settings')"><Settings :size="17"/></button><button class="icon-button" aria-label="导入资料" title="导入资料 · ⌘ / Ctrl O" :disabled="!store.snapshot" @click="showImport=true"><Upload :size="17"/></button><button class="icon-button" aria-label="新建课程" title="新建课程 · ⌘ / Ctrl N" :disabled="!store.snapshot" @click="editCourse()"><Plus :size="18"/></button></div></div><div v-if="store.snapshot" class="app-body"><Sidebar @edit-course="editCourse"/><main class="main-pane"><LibraryView v-if="!['plans','pending','timetable','assistant','settings'].includes(store.route)" :key="store.route" @import="showImport=true" @edit-course="editCourse" @website="openWebsite()"/><PlansView v-else-if="store.route==='plans'||store.route==='pending'"/><TimetableView v-else-if="store.route==='timetable'" @website="openWebsite('timetable')"/><SettingsView v-else-if="store.route==='settings'" @website="openWebsite()"/><ChatView v-show="store.route==='assistant'"/><footer class="statusbar"><LoaderCircle v-if="store.busy" :size="12" class="spinning"/><span v-else class="status-dot"/><span>{{store.status}}</span><span class="spacer"/><span>{{store.state.courses.length}} 门课程 · {{store.state.materials.length}} 份资料</span><span class="status-separator"/><span>本地资料库</span></footer></main></div><div v-else class="startup-state"><LoaderCircle v-if="!loaded" :size="30" class="spinning"/><AlertCircle v-else :size="30"/><h1>{{loaded?'资料库未能打开':'正在打开课屿'}}</h1><p>{{loaded?'请检查资料库路径和访问权限，再重新打开。':'正在读取本地课程与资料…'}}</p><button v-if="loaded&&hasAPI" @click="store.chooseLibrary(false)">选择 Desktop 资料库</button></div><div v-if="store.error" class="error-toast" role="alert"><AlertCircle :size="18"/><div><strong>操作未完成</strong><p>{{store.error}}</p></div><button class="icon-button" aria-label="关闭错误提示" @click="store.error=''"><X :size="17"/></button></div><CourseEditor v-if="courseEditor!==undefined" :course="courseEditor??undefined" @close="courseEditor=undefined"/><ImportDialog v-if="showImport" @close="showImport=false"/><TaskEditor v-if="showTask" @close="showTask=false"/><WebsiteDialog v-if="showWebsite" :initial-kind="websiteKind" @close="showWebsite=false"/><Modal v-if="store.confirmRequest" :title="store.confirmRequest.title" @close="store.decide(false)"><p class="confirm-detail">{{store.confirmRequest.detail}}</p><div class="dialog-actions"><span class="spacer"/><button @click="store.decide(false)">取消</button><button class="primary" @click="store.decide(true)">{{store.confirmRequest.action}}</button></div></Modal></div></template>
